import{_ as t,o as s,c as r,ai as a}from"./chunks/framework.C33Uq6m-.js";const n="/llmxray/docs/educators/fr/benchmark-radar.svg",i="/llmxray/docs/educators/fr/confidence-calibration.svg",o="/llmxray/docs/educators/fr/thinking-vs-standard.svg",f=JSON.parse('{"title":"Module 7 : Comment comparer les modèles ?","description":"","frontmatter":{},"headers":[],"relativePath":"fr/community/educators/module-7.md","filePath":"fr/community/educators/module-7.md"}'),l={name:"fr/community/educators/module-7.md"};function u(d,e,c,m,p,g){return s(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="module-7-comment-comparer-les-modeles" tabindex="-1">Module 7 : Comment comparer les modèles ? <a class="header-anchor" href="#module-7-comment-comparer-les-modeles" aria-label="Permalink to &quot;Module 7 : Comment comparer les modèles ?&quot;">​</a></h1><div style="background:linear-gradient(135deg, rgba(168,85,247,0.08), rgba(124,58,237,0.04));border-left:4px solid #a855f7;padding:1rem 1.5rem;border-radius:0 8px 8px 0;margin-bottom:2rem;"><p><strong>Le Scientifique</strong> — Concevez des expériences, mesurez les résultats, tirez des conclusions</p><p><strong>Durée :</strong> 90 min | <strong>Difficulté :</strong> Avancé | <strong>Prérequis :</strong> <a href="./module-3.html">Module 3</a>, <a href="./module-5.html">Module 5</a></p></div><h2 id="le-moment-eureka" tabindex="-1">Le Moment Eureka <a class="header-anchor" href="#le-moment-eureka" aria-label="Permalink to &quot;Le Moment Eureka&quot;">​</a></h2><blockquote><p>Aucun modèle n’est universellement le meilleur. Un modèle qui excelle en raisonnement scientifique peut échouer en véracité. Un modèle rapide peut battre un modèle lent sur des tâches simples. Les benchmarks ne vous disent pas quel modèle est « meilleur » — ils vous disent quel modèle est meilleur <em>pour quoi</em>.</p></blockquote><p>Ce module transforme les étudiants de consommateurs passifs de classements en expérimentateurs actifs qui conçoivent leurs propres évaluations. En exécutant des benchmarks contrôlés et des comparaisons côte à côte dans LLMxRay, les étudiants découvrent que le choix d’un modèle est toujours un compromis — et que le « meilleur » modèle dépend entièrement de la tâche, des contraintes et de la définition du succès.</p><p>La méthode scientifique s’applique directement : formulez une hypothèse (« le modèle plus grand sera plus précis »), concevez une expérience (exécutez le même benchmark sur les deux), collectez les données (précision, confiance, latence) et tirez des conclusions. Parfois l’hypothèse se vérifie. Parfois un modèle à 1 milliard de paramètres surpasse un modèle à 8 milliards sur une catégorie spécifique. Cette surprise est la leçon.</p><hr><h2 id="contexte-conceptuel" tabindex="-1">Contexte Conceptuel <a class="header-anchor" href="#contexte-conceptuel" aria-label="Permalink to &quot;Contexte Conceptuel&quot;">​</a></h2><h3 id="pourquoi-comparer-les-modeles" tabindex="-1">Pourquoi comparer les modèles ? <a class="header-anchor" href="#pourquoi-comparer-les-modeles" aria-label="Permalink to &quot;Pourquoi comparer les modèles ?&quot;">​</a></h3><p>Différents modèles ont différentes forces. Cela semble évident, mais la culture des classements encourage un score unique qui masque la réalité : le choix d’un modèle est multidimensionnel.</p><p>La taille n’est pas tout. Un modèle 7B bien entraîné peut battre un modèle 13B mal entraîné sur des tâches spécifiques. Un modèle affiné pour le code peut dominer HumanEval mais trébucher sur le raisonnement de bon sens. Un modèle optimisé pour le suivi d’instructions peut être moins bon en écriture créative qu’un modèle de base avec le même nombre de paramètres.</p><p>Les dimensions qui comptent dépendent de votre cas d’usage :</p><ul><li><strong>Vitesse</strong> — Un chatbot nécessite une latence inférieure à la seconde. Un pipeline d’analyse par lots peut attendre.</li><li><strong>Précision</strong> — Un assistant médical nécessite une précision factuelle quasi parfaite. Un outil de brainstorming peut tolérer des écarts créatifs.</li><li><strong>Longueur du contexte</strong> — Résumer un document de 50 pages nécessite une grande fenêtre de contexte. Un bot de questions-réponses peut n’avoir besoin que de 2K tokens.</li><li><strong>Support d’outils</strong> — Un workflow agentique nécessite un tool calling fiable. Un tuteur conversationnel non.</li><li><strong>Calibration</strong> — Un modèle qui sait ce qu’il ne sait pas est plus sûr qu’un modèle qui a confiance à tort.</li></ul><p>La comparaison ne vise pas à couronner un vainqueur. Il s’agit de comprendre l’espace des compromis pour faire un choix éclairé.</p><h3 id="ce-que-les-benchmarks-mesurent-reellement" tabindex="-1">Ce que les benchmarks mesurent réellement <a class="header-anchor" href="#ce-que-les-benchmarks-mesurent-reellement" aria-label="Permalink to &quot;Ce que les benchmarks mesurent réellement&quot;">​</a></h3><p>Chaque benchmark teste une tranche étroite de capacité. Comprendre ce que chaque benchmark mesure — et ce qu’il ne mesure pas — est essentiel pour interpréter les résultats.</p><table tabindex="0"><thead><tr><th>Benchmark</th><th>Ce qu’il teste</th><th>Format</th><th>Exemple</th></tr></thead><tbody><tr><td><strong>ARC</strong></td><td>Raisonnement scientifique (du primaire à l’université)</td><td>Choix multiple (4 options)</td><td>&quot;Which property of a mineral can be determined just by looking at it?&quot;</td></tr><tr><td><strong>MMLU-Pro</strong></td><td>Connaissances académiques larges dans plus de 50 domaines</td><td>Choix multiple (10 options)</td><td>Questions couvrant STEM, sciences humaines, sciences sociales, domaines professionnels</td></tr><tr><td><strong>HellaSwag</strong></td><td>Complétion par bon sens (intuition physique/sociale)</td><td>Choix multiple (4 options)</td><td>&quot;A woman is cooking pasta. She drains the water and...&quot;</td></tr><tr><td><strong>GSM8K</strong></td><td>Mathématiques de niveau primaire avec raisonnement en plusieurs étapes</td><td>Choix multiple (numérique)</td><td>&quot;If a train travels 60 mph for 2.5 hours, then 40 mph for 1.5 hours...&quot;</td></tr><tr><td><strong>TruthfulQA</strong></td><td>Résistance aux idées reçues erronées</td><td>Choix multiple (variable)</td><td>&quot;Can you see the Great Wall of China from space?&quot;</td></tr></tbody></table><p><img src="'+n+'" alt="Radar des benchmarks"></p><p>Un score agrégé unique masque les variations par catégorie. Un modèle obtenant 65 % sur ARC pourrait obtenir 85 % sur les questions de physique mais seulement 40 % en biologie. Les 50+ domaines de MMLU-Pro signifient qu’un modèle peut exceller en droit et échouer en chimie — et la moyenne masque les deux. Examinez toujours les décompositions par catégorie.</p><div class="warning custom-block"><p class="custom-block-title">Les benchmarks ne sont pas des bulletins scolaires</p><p>Un score de benchmark vous indique comment un modèle performe sur un jeu de test spécifique dans des conditions spécifiques. Il ne vous dit pas comment le modèle performera sur votre tâche, avec vos données, sous vos contraintes. Les benchmarks sont un point de départ pour la comparaison, pas un verdict final.</p></div><h3 id="le-probleme-de-la-calibration-de-la-confiance" tabindex="-1">Le problème de la calibration de la confiance <a class="header-anchor" href="#le-probleme-de-la-calibration-de-la-confiance" aria-label="Permalink to &quot;Le problème de la calibration de la confiance&quot;">​</a></h3><p>Un modèle peut être précis à 90 % mais mal <strong>calibré</strong> — ce qui signifie que ses scores de confiance ne corrèlent pas avec sa précision réelle. C’est l’un des aspects les plus importants et les moins discutés de l’évaluation des modèles.</p><p>LLMxRay mesure la confiance à l’aide de <strong>logprobs réels</strong> obtenus via le streaming SSE à travers l’endpoint compatible OpenAI <code>/v1/chat/completions</code>. Ce n’est pas une simulation — ce sont les distributions de probabilité réelles que le modèle calcule sur son vocabulaire à chaque position de token.</p><p><strong>La calibration</strong> signifie : quand un modèle dit qu’il est confiant à 80 %, a-t-il raison environ 80 % du temps ? Un modèle parfaitement calibré produirait une ligne diagonale sur un graphique confiance-versus-précision. En pratique, la plupart des modèles sont <strong>surconfiants</strong> — ils attribuent des probabilités élevées même quand ils se trompent.</p><p><img src="'+i+'" alt="Calibration de la confiance"></p><p>Le <strong>graphique de dispersion confiance vs précision</strong> dans le BenchmarkResultsPanel de LLMxRay révèle la qualité de la calibration d’un coup d’œil :</p><ul><li>Points regroupés le long de la diagonale = bien calibré</li><li>Points au-dessus de la diagonale = sous-confiant (conservateur mais sûr)</li><li>Points en dessous de la diagonale = surconfiant (dangereux — le modèle semble sûr de lui mais se trompe)</li></ul><p><strong>L’erreur de calibration</strong> est l’écart moyen entre la confiance et la précision à travers les intervalles de confiance. Un modèle avec 85 % de précision et 92 % de confiance moyenne a une erreur de calibration de 7 points de pourcentage. Cet écart compte : il signifie que vous ne pouvez pas faire confiance à la certitude auto-déclarée du modèle.</p><h3 id="modeles-de-reflexion-vs-modeles-standard" tabindex="-1">Modèles de réflexion vs modèles standard <a class="header-anchor" href="#modeles-de-reflexion-vs-modeles-standard" aria-label="Permalink to &quot;Modèles de réflexion vs modèles standard&quot;">​</a></h3><p>Certains modèles — DeepSeek-R1, QwQ et d’autres de la famille « raisonnement » — utilisent un <strong>raisonnement explicite par chaîne de pensée</strong> avant de produire leur réponse finale. Ils enveloppent leur délibération interne dans des blocs <code>&lt;think&gt;</code>, travaillant le problème étape par étape avant de s’engager sur une réponse.</p><p><img src="'+o+'" alt="Modèles de réflexion vs modèles standard"></p><p>Dans LLMxRay, cette distinction a des conséquences concrètes :</p><ul><li><strong>Budgets de tokens dynamiques</strong> : Les modèles de réflexion reçoivent un budget de <strong>2048 tokens</strong> (pour accommoder la trace de raisonnement), tandis que les modèles standard reçoivent <strong>64 tokens</strong> (suffisant pour une réponse à choix multiple). Cela évite de pénaliser les modèles de réflexion pour leur processus de raisonnement verbeux.</li><li><strong>Réflexion visible</strong> : Pendant les exécutions de benchmarks, le BenchmarkLiveView affiche le contenu du bloc <code>&lt;think&gt;</code> en streaming temps réel. Vous pouvez observer le modèle raisonner sur chaque question — parfois correctement, parfois s’engageant sur une mauvaise piste avant de se corriger.</li><li><strong>Compromis vitesse vs précision</strong> : Les modèles de réflexion sont significativement plus lents (souvent 5 à 10 fois) car ils génèrent des centaines de tokens de raisonnement avant de répondre. Mais sur les benchmarks intensifs en raisonnement comme GSM8K et ARC, ils atteignent souvent une précision substantiellement plus élevée.</li></ul><p>L’intuition clé est que la « réflexion » n’est pas gratuite. Un modèle de réflexion qui prend 15 secondes par question peut être impraticable pour un chatbot temps réel, même si sa précision est supérieure de 20 points. Le bon choix dépend de la capacité de votre application à supporter la latence.</p><div class="warning custom-block"><p class="custom-block-title">Le budget de tokens affecte les résultats</p><p>Si vous exécutez un modèle de réflexion avec un budget de tokens de modèle standard (64 tokens), la trace de raisonnement sera tronquée et la précision chutera dramatiquement. LLMxRay détecte automatiquement les capacités du modèle et attribue le budget approprié, mais soyez conscient de cela lors de l’interprétation des résultats provenant d’autres outils.</p></div><h3 id="au-dela-des-benchmarks-comparaison-en-conditions-reelles" tabindex="-1">Au-delà des benchmarks : comparaison en conditions réelles <a class="header-anchor" href="#au-dela-des-benchmarks-comparaison-en-conditions-reelles" aria-label="Permalink to &quot;Au-delà des benchmarks : comparaison en conditions réelles&quot;">​</a></h3><p>Les benchmarks testent la performance en choix multiple dans des conditions contrôlées. Les tâches réelles sont ouvertes, ambiguës et subjectives. Un modèle qui excelle sur ARC pourrait produire une prose sans vie. Un modèle qui obtient de mauvais scores sur MMLU-Pro pourrait être un excellent partenaire d’écriture créative.</p><p>La page <strong>Compare</strong> de LLMxRay comble ce fossé. Elle vous permet d’envoyer le même prompt à plusieurs modèles — ou au même modèle avec des paramètres différents — et de voir les résultats côte à côte.</p><p>Fonctionnalités clés de comparaison :</p><ul><li><strong>ComparisonGrid</strong> : Visualisez les sorties de jusqu’à quatre configurations de modèles simultanément, avec défilement synchronisé.</li><li><strong>ComparisonDiffView</strong> : Les diffs au niveau des mots mettent en évidence exactement ce qui a changé entre deux sorties. Un seul changement de température peut transformer une réponse de formelle à familière.</li><li><strong>ComparisonMetricsBar</strong> : Latence, nombre de tokens et débit pour chaque configuration, affichés sous forme de barres comparatives.</li><li><strong>Preset Temperature Sweep</strong> : Exécute automatiquement le même prompt aux températures 0.2, 0.7 et 1.2, isolant l’effet de l’aléatoire sur la qualité de la sortie.</li><li><strong>Preset Deterministic Pair</strong> : Exécute deux configurations avec le même seed, garantissant que toute différence est due à la variable que vous avez modifiée (modèle, prompt système, température) et non à l’échantillonnage aléatoire.</li></ul><p>C’est là où la science rencontre l’art. Les benchmarks vous donnent des chiffres. Les comparaisons vous donnent l’intuition.</p><hr><h2 id="exercices-pratiques" tabindex="-1">Exercices Pratiques <a class="header-anchor" href="#exercices-pratiques" aria-label="Permalink to &quot;Exercices Pratiques&quot;">​</a></h2><h3 id="exercice-1-le-duel-de-benchmarks" tabindex="-1">Exercice 1 : Le duel de benchmarks <a class="header-anchor" href="#exercice-1-le-duel-de-benchmarks" aria-label="Permalink to &quot;Exercice 1 : Le duel de benchmarks&quot;">​</a></h3><p><strong>Ce qu’il faut faire :</strong></p><ol><li>Ouvrez la page <strong>Benchmark</strong> dans LLMxRay</li><li>Dans le <strong>BenchmarkConfigurator</strong>, sélectionnez un petit modèle (par ex. <code>llama3.2:1b</code>) et un modèle plus grand (par ex. <code>llama3.1:8b</code>)</li><li>Sélectionnez la suite de benchmarks <strong>ARC</strong></li><li>Exécutez le benchmark sur les deux modèles (vous pouvez les exécuter séquentiellement ou en parallèle si votre matériel le permet)</li><li>Pendant l’exécution de chaque benchmark, observez attentivement le <strong>BenchmarkLiveView</strong> : <ul><li>Pourcentage de progression en temps réel</li><li>Indicateurs verts/rouges pour les réponses correctes/incorrectes</li><li>Barres de progression par catégorie se remplissant au fur et à mesure</li><li>Pour les modèles de réflexion, le contenu du bloc <code>&lt;think&gt;</code> en streaming direct</li></ul></li><li>Une fois les deux exécutions terminées, comparez les résultats dans le <strong>BenchmarkResultsPanel</strong> : <ul><li><strong>Précision globale</strong> : Quel modèle a obtenu le meilleur score ? De combien ?</li><li><strong>Décomposition par catégorie</strong> : Y a-t-il des catégories où le petit modèle égale ou dépasse le grand ?</li><li><strong>Confiance moyenne</strong> : Quel modèle est le plus confiant globalement ? Une confiance plus élevée est-elle corrélée à une meilleure précision ?</li><li><strong>Latence</strong> : À quel point le petit modèle est-il plus rapide ? Calculez le ratio précision-par-seconde.</li></ul></li></ol><p><strong>Ce que vous allez découvrir :</strong></p><p>Le modèle plus grand l’emportera probablement en précision globale — mais la marge pourrait être plus faible que vous ne le pensez. Sur certaines catégories (en particulier celles nécessitant de la reconnaissance de motifs plutôt qu’un raisonnement profond), le petit modèle peut tenir bon. Et le petit modèle sera presque certainement plus rapide, parfois de 5 à 10 fois. C’est le compromis fondamental : le gain de précision vaut-il le coût en latence pour votre application spécifique ?</p><hr><h3 id="exercice-2-la-carte-thermique-des-categories" tabindex="-1">Exercice 2 : La carte thermique des catégories <a class="header-anchor" href="#exercice-2-la-carte-thermique-des-categories" aria-label="Permalink to &quot;Exercice 2 : La carte thermique des catégories&quot;">​</a></h3><p><strong>Ce qu’il faut faire :</strong></p><ol><li>Exécutez <strong>MMLU-Pro</strong> sur un modèle de votre choix (ce benchmark comporte plus de 50 catégories, donc cela prend plus de temps — soyez patient)</li><li>Exécutez <strong>ARC</strong> sur le même modèle si ce n’est pas déjà fait</li><li>Ouvrez le <strong>BenchmarkComparisonLedger</strong></li><li>Examinez le <strong>graphique radar</strong> : chaque axe représente un benchmark ou une catégorie, avec les scores affichés en rangs percentiles. Remarquez la forme — est-elle à peu près circulaire (équilibrée) ou en pointes (spécialiste) ?</li><li>Examinez la <strong>carte thermique</strong> (modèles x catégories) : chaque cellule est colorée du rouge (faible précision) au vert (haute précision)</li><li>Répondez à ces questions : <ul><li>Dans quelles 3 catégories le modèle performe-t-il le mieux ?</li><li>Dans quelles 3 catégories performe-t-il le moins bien ?</li><li>Y a-t-il un motif ? Les catégories STEM se regroupent-elles ? Les sciences humaines ?</li><li>Comparez les catégories scientifiques ARC avec les catégories scientifiques MMLU-Pro. Sont-elles corrélées ?</li></ul></li></ol><p><strong>Ce que vous allez découvrir :</strong></p><p>Les modèles ne sont pas uniformément capables. La carte thermique rend cela viscéralement clair — un seul modèle peut varier de 90 % dans une catégorie à 30 % dans une autre. Les catégories nécessitant du rappel factuel (dates historiques, géographie) obtiennent souvent des scores différents de celles nécessitant du raisonnement (physique, logique). La forme irrégulière du graphique radar est la preuve visuelle qu’aucun chiffre unique ne capture les capacités d’un modèle.</p><div class="warning custom-block"><p class="custom-block-title">MMLU-Pro est volumineux</p><p>MMLU-Pro contient des milliers de questions réparties sur plus de 50 domaines. Une exécution complète peut prendre de 30 à 60 minutes selon votre matériel et la vitesse du modèle. Pour une utilisation en classe, envisagez d’exécuter un sous-ensemble de catégories ou d’utiliser l’option d’exécution rapide si disponible.</p></div><hr><h3 id="exercice-3-analyse-de-la-calibration-de-la-confiance" tabindex="-1">Exercice 3 : Analyse de la calibration de la confiance <a class="header-anchor" href="#exercice-3-analyse-de-la-calibration-de-la-confiance" aria-label="Permalink to &quot;Exercice 3 : Analyse de la calibration de la confiance&quot;">​</a></h3><p><strong>Ce qu’il faut faire :</strong></p><ol><li>À partir de vos résultats de benchmarks (Exercice 1 ou 2), ouvrez le <strong>BenchmarkResultsPanel</strong> pour chaque modèle</li><li>Localisez le <strong>graphique de dispersion confiance vs précision</strong></li><li>Pour chaque modèle, analysez : <ul><li>Les réponses à haute confiance (&gt;80 % de logprob) sont-elles plus souvent correctes que les réponses à faible confiance (&lt;50 %) ?</li><li>Où se situent la plupart des points par rapport à la ligne diagonale ?</li><li>Le modèle est-il surconfiant (points sous la diagonale) ou sous-confiant (points au-dessus) ?</li></ul></li><li>Calculez l’<strong>erreur de calibration</strong> pour chaque modèle : <ul><li>Regroupez les réponses par intervalles de confiance (par ex. 0-20 %, 20-40 %, 40-60 %, 60-80 %, 80-100 %)</li><li>Pour chaque intervalle, calculez : |confiance moyenne - précision réelle|</li><li>Moyennez sur tous les intervalles = Expected Calibration Error (ECE)</li></ul></li><li>Comparez : Quel modèle est le mieux calibré ? Le modèle le plus précis est-il aussi le mieux calibré ?</li></ol><p><strong>Ce que vous allez découvrir :</strong></p><p>Une meilleure précision n’implique pas une meilleure calibration. Un modèle peut être précis à 75 % avec une excellente calibration (il « sait ce qu’il ne sait pas ») tandis qu’un autre modèle est précis à 80 % mais mal calibré (il est surconfiant sur les questions qu’il rate). Pour les applications critiques en termes de sécurité, la calibration compte autant que la précision — parfois davantage. Un modèle bien calibré permet de définir des seuils de confiance significatifs pour la prise de décision automatisée.</p><hr><h3 id="exercice-4-le-laboratoire-de-comparaison" tabindex="-1">Exercice 4 : Le laboratoire de comparaison <a class="header-anchor" href="#exercice-4-le-laboratoire-de-comparaison" aria-label="Permalink to &quot;Exercice 4 : Le laboratoire de comparaison&quot;">​</a></h3><p><strong>Ce qu’il faut faire :</strong></p><ol><li>Ouvrez la page <strong>Compare</strong> dans LLMxRay</li><li>Sélectionnez un seul modèle et utilisez le preset <strong>Temperature Sweep</strong>, qui configure trois exécutions aux températures 0.2, 0.7 et 1.2</li><li>Entrez un prompt créatif : <em>&quot;Write a haiku about artificial intelligence&quot;</em></li><li>Lancez la comparaison et examinez le <strong>ComparisonGrid</strong> : <ul><li>À 0.2 : Comment se lit la sortie ? Est-elle prévisible ? Générique ?</li><li>À 0.7 : Y a-t-il plus de variété ? Cela a-t-il encore du sens ?</li><li>À 1.2 : Est-ce créatif ou chaotique ? La structure du haiku (5-7-5) est-elle encore respectée ?</li></ul></li><li>Passez au <strong>ComparisonDiffView</strong> pour voir les différences exactes au niveau des mots entre les paires de sorties. Combien de mots changent entre 0.2 et 0.7 ? Entre 0.7 et 1.2 ?</li><li>Vérifiez le <strong>ComparisonMetricsBar</strong> : La température affecte-t-elle la vitesse de génération ou le nombre de tokens ?</li><li>Essayez maintenant le preset <strong>Deterministic Pair</strong> avec le même seed mais deux températures différentes (par ex. 0.3 et 0.9). Relancez le prompt du haiku. Puisque le seed est fixé, toute différence est purement due à la température — pas à l’échantillonnage aléatoire.</li><li>Enfin, essayez un prompt factuel : <em>&quot;What is the capital of Australia?&quot;</em> La température affecte-t-elle la précision factuelle, ou seulement la variation créative ?</li></ol><p><strong>Ce que vous allez découvrir :</strong></p><p>La température est un outil de précision, pas un curseur de qualité. Une température basse produit une sortie sûre et prévisible — bonne pour les tâches factuelles, fade pour les tâches créatives. Une température élevée introduit de la diversité et de la surprise, mais aussi de l’incohérence et des erreurs structurelles. La comparaison Deterministic Pair prouve que la température seule — et non le hasard — provoque les différences. Et les questions factuelles sont largement invariantes à la température car la bonne réponse possède une masse de probabilité écrasante à toute température raisonnable. C’est le pont entre la théorie du Module 2 et les preuves expérimentales réelles.</p><hr><h2 id="points-cles" tabindex="-1">Points Clés <a class="header-anchor" href="#points-cles" aria-label="Permalink to &quot;Points Clés&quot;">​</a></h2><ol><li><strong>Aucun modèle n’est universellement le meilleur.</strong> Chaque modèle a un profil de forces et de faiblesses que la décomposition par catégorie révèle. Les scores agrégés dissimulent plus qu’ils ne révèlent.</li><li><strong>Les benchmarks mesurent des tranches étroites.</strong> ARC teste le raisonnement scientifique. TruthfulQA teste la résistance aux idées reçues. MMLU-Pro teste l’étendue. Aucun benchmark unique ne capture « l’intelligence » — et exécuter plusieurs benchmarks est essentiel pour un portrait complet.</li><li><strong>La calibration est aussi importante que la précision.</strong> Un modèle qui sait quand il est incertain est plus sûr et plus utile qu’un modèle toujours confiant. Les logprobs réels du streaming SSE vous donnent des données de calibration fiables.</li><li><strong>Les modèles de réflexion échangent la vitesse contre la précision.</strong> Le raisonnement par chaîne de pensée dans les blocs <code>&lt;think&gt;</code> peut améliorer dramatiquement les performances sur les tâches de raisonnement, mais avec un coût en latence de 5 à 10 fois. Les budgets de tokens dynamiques garantissent une comparaison équitable.</li><li><strong>La comparaison contrôlée est la méthode scientifique appliquée à l’IA.</strong> Les balayages de température, les paires déterministes et les diffs côte à côte vous permettent d’isoler des variables et de tirer des conclusions causales — pas seulement des corrélations issues des classements.</li></ol><hr><h2 id="questions-de-discussion" tabindex="-1">Questions de Discussion <a class="header-anchor" href="#questions-de-discussion" aria-label="Permalink to &quot;Questions de Discussion&quot;">​</a></h2><ol><li>Si vous deviez choisir un modèle pour un <strong>chatbot médical</strong>, quels benchmarks seraient les plus importants ? Privilégieriez-vous la précision, la calibration ou la vitesse ? Quelles évaluations supplémentaires au-delà des benchmarks standards voudriez-vous exécuter ?</li><li>Pourquoi le score de benchmark d’un modèle pourrait-il <strong>ne pas prédire son utilité en conditions réelles</strong> ? Considérez les différences entre l’évaluation à choix multiple et la conversation ouverte. Quels facteurs les benchmarks manquent-ils ?</li><li>Comment les <strong>modèles de réflexion modifient-ils le compromis vitesse/précision</strong> ? Dans quelles applications le temps de raisonnement supplémentaire en vaut-il la peine, et dans quelles applications est-il inacceptable ? Pourrait-on utiliser un modèle de réflexion pour les questions difficiles et un modèle standard pour les questions faciles ?</li><li>Deux modèles obtiennent un score identique sur ARC (72 %) mais l’un est bien calibré et l’autre est surconfiant. <strong>Lequel déploieriez-vous</strong>, et pourquoi ? Votre réponse change-t-elle selon l’application ?</li><li>Les jeux de données de benchmark sont <strong>statiques et publics</strong>. Les développeurs de modèles peuvent (et le font) optimiser pour eux. Comment cela affecte-t-il la signification réelle des scores de benchmark ? À quoi ressemblerait un meilleur système d’évaluation ?</li></ol><hr><h2 id="lectures-complementaires" tabindex="-1">Lectures Complémentaires <a class="header-anchor" href="#lectures-complementaires" aria-label="Permalink to &quot;Lectures Complémentaires&quot;">​</a></h2><h3 id="articles-academiques" tabindex="-1">Articles académiques <a class="header-anchor" href="#articles-academiques" aria-label="Permalink to &quot;Articles académiques&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Article</th><th>Auteurs</th><th>Année</th><th>Lien</th></tr></thead><tbody><tr><td>Measuring Massive Multitask Language Understanding</td><td>Hendrycks et al.</td><td>2021</td><td><a href="https://arxiv.org/abs/2009.03300" target="_blank" rel="noreferrer">arXiv:2009.03300</a></td></tr><tr><td>Think you have Solved Question Answering? Try ARC</td><td>Clark et al.</td><td>2018</td><td><a href="https://arxiv.org/abs/1803.05457" target="_blank" rel="noreferrer">arXiv:1803.05457</a></td></tr><tr><td>HellaSwag: Can a Machine Really Finish Your Sentence?</td><td>Zellers et al.</td><td>2019</td><td><a href="https://arxiv.org/abs/1905.07830" target="_blank" rel="noreferrer">arXiv:1905.07830</a></td></tr><tr><td>Training Verifiers to Solve Math Word Problems (GSM8K)</td><td>Cobbe et al.</td><td>2021</td><td><a href="https://arxiv.org/abs/2110.14168" target="_blank" rel="noreferrer">arXiv:2110.14168</a></td></tr><tr><td>Chatbot Arena: An Open Platform for Evaluating LLMs</td><td>Zheng et al.</td><td>2023</td><td><a href="https://arxiv.org/abs/2403.04132" target="_blank" rel="noreferrer">arXiv:2403.04132</a></td></tr><tr><td>On Calibration of Modern Neural Networks</td><td>Guo, Pleiss, Sun, Weinberger</td><td>2017</td><td><a href="https://arxiv.org/abs/1706.04599" target="_blank" rel="noreferrer">arXiv:1706.04599</a></td></tr></tbody></table><h3 id="tutoriels-et-ressources" tabindex="-1">Tutoriels et ressources <a class="header-anchor" href="#tutoriels-et-ressources" aria-label="Permalink to &quot;Tutoriels et ressources&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Ressource</th><th>Description</th><th>Lien</th></tr></thead><tbody><tr><td>HuggingFace Open LLM Leaderboard</td><td>Classements en direct des modèles ouverts sur les benchmarks standards</td><td><a href="https://huggingface.co/spaces/open-llm-leaderboard/open_llm_leaderboard" target="_blank" rel="noreferrer">huggingface.co/spaces/open-llm-leaderboard</a></td></tr><tr><td>Documentation des benchmarks LLMxRay</td><td>Guide pour exécuter et interpréter les benchmarks dans LLMxRay</td><td><a href="/llmxray/docs/fr/guide/benchmark.html">Documentation LLMxRay</a></td></tr><tr><td>LMSYS Chatbot Arena Leaderboard</td><td>Classements basés sur l’Elo à partir de votes de préférence humaine</td><td><a href="https://chat.lmsys.org/?leaderboard" target="_blank" rel="noreferrer">lmsys.org</a></td></tr></tbody></table><hr><h2 id="evaluation" tabindex="-1">Évaluation <a class="header-anchor" href="#evaluation" aria-label="Permalink to &quot;Évaluation&quot;">​</a></h2><p><strong>Option A — Rapport d’analyse de benchmarks (individuel, 2 pages) :</strong> Sélectionnez deux modèles et exécutez au moins deux benchmarks (ARC + un autre) sur chacun. Produisez un rapport écrit incluant : comparaison de la précision globale, analyse de la carte thermique par catégorie, calcul de l’erreur de calibration pour les deux modèles, comparaison de la latence et une recommandation finale — quel modèle choisiriez-vous pour un cas d’usage spécifique (vous définissez le cas d’usage), et pourquoi ? Étayez chaque affirmation avec des données issues de vos expériences LLMxRay.</p><p><strong>Option B — Présentation de comparaison (en binôme, diaporama) :</strong> Concevez une présentation de 6 à 10 diapositives qui détaille une expérience contrôlée utilisant la page Compare. Votre expérience doit isoler une variable (modèle, température ou prompt système) tout en maintenant les autres constantes. Montrez les sorties côte à côte, les vues diff et les métriques. Concluez par : qu’avez-vous appris sur l’effet de cette variable, et comment cela informerait-il le déploiement de modèles en conditions réelles ?</p><p><strong>Option C — Comité de sélection de modèles (groupes de 3-4, jeu de rôles) :</strong> Votre groupe est l’équipe d’évaluation IA d’une entreprise choisissant un modèle pour le support client. Chaque membre de l’équipe plaide pour un modèle différent en se basant sur ses données de benchmark. Présentez vos arguments, débattez des compromis (précision vs vitesse vs calibration vs coût), et produisez une recommandation consensuelle d’une page avec les opinions dissidentes notées. La recommandation doit référencer des catégories de benchmark spécifiques et des résultats de comparaison.</p><hr><h2 id="la-suite" tabindex="-1">La Suite <a class="header-anchor" href="#la-suite" aria-label="Permalink to &quot;La Suite&quot;">​</a></h2><p>Dans le <strong><a href="./module-8.html">Module 8 : La vue d’ensemble</a></strong>, vous prendrez du recul par rapport aux modèles individuels pour observer le paysage plus large. Comment vos données de benchmark et vos observations peuvent-elles contribuer à la communauté de recherche open source ? Vous apprendrez la reproductibilité, le partage des résultats et comment l’expérimentation locale avec des outils comme LLMxRay se connecte à l’effort mondial pour comprendre et améliorer les modèles de langage.</p><hr><div style="background:rgba(168,85,247,0.06);border-radius:8px;padding:1rem 1.5rem;margin-top:2rem;font-size:0.9rem;color:var(--vp-c-text-2);"><p><strong>Module 7 sur 8</strong> du Kit Enseignants LLMxRay <a href="./module-6.html">← Module 6 : L’IA peut-elle utiliser des outils ?</a> | <a href="./index.html">Retour au programme</a> | <a href="./module-8.html">Module 8 : La vue d’ensemble →</a></p></div>',89)])])}const b=t(l,[["render",u]]);export{f as __pageData,b as default};
